import React, { createContext, useContext, useEffect, useId, useLayoutEffect, useRef, useState } from 'react';
import { getTabsListVariantKey, getTabsState, observeTabsIndicator, tabsStyleKeys } from '../lib/core';
import type { TabsBaseProps, TabsListBaseProps, TabsTriggerBaseProps, TabsContentBaseProps } from '../lib/core';
import styles from './tabs.module.scss';

interface TabsContextValue {
	value: string;
	orientation: 'horizontal' | 'vertical';
	baseId: string;
	select: (value: string) => void;
}

const TabsContext = createContext<TabsContextValue | null>(null);
const useBrowserLayoutEffect = typeof window === 'undefined' ? useEffect : useLayoutEffect;

function useTabsContext(): TabsContextValue {
	const context = useContext(TabsContext);
	if (!context) {
		throw new Error('Tabs sub-components must be used within <Tabs>.');
	}
	return context;
}

export interface TabsProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'value' | 'defaultValue'>, TabsBaseProps {}

const Tabs = React.forwardRef<HTMLDivElement, TabsProps>(({ className = '', value, defaultValue = '', orientation = 'horizontal', onValueChange, children, ...props }, ref) => {
	const [internalValue, setInternalValue] = useState(defaultValue);
	const currentValue = value !== undefined ? value : internalValue;
	const baseId = useId();

	function select(next: string) {
		if (value === undefined) {
			setInternalValue(next);
		}
		onValueChange?.(next);
	}

	return (
		<TabsContext.Provider value={{ value: currentValue, orientation, baseId, select }}>
			<div ref={ref} data-orientation={orientation} className={`${styles[tabsStyleKeys.root]} ${className}`} {...props}>
				{children}
			</div>
		</TabsContext.Provider>
	);
});
Tabs.displayName = 'Tabs';

export interface TabsListProps extends React.HTMLAttributes<HTMLDivElement>, TabsListBaseProps {}

const TabsList = React.forwardRef<HTMLDivElement, TabsListProps>(({ className = '', variant = 'default', children, onKeyDown, ...props }, ref) => {
	const context = useTabsContext();
	const variantKey = getTabsListVariantKey(variant);
	const isVertical = context.orientation === 'vertical';
	const listRef = useRef<HTMLDivElement>(null);
	const indicatorRef = useRef<HTMLSpanElement>(null);
	const measurement = useRef<ReturnType<typeof observeTabsIndicator> | null>(null);

	useBrowserLayoutEffect(() => {
		if (!listRef.current || !indicatorRef.current) return;
		const observer = observeTabsIndicator(listRef.current, indicatorRef.current);
		measurement.current = observer;
		return () => {
			observer.disconnect();
			measurement.current = null;
		};
	}, []);
	useBrowserLayoutEffect(() => measurement.current?.update());

	function handleKeyDown(event: React.KeyboardEvent<HTMLDivElement>) {
		onKeyDown?.(event);

		const nextKey = isVertical ? 'ArrowDown' : 'ArrowRight';
		const prevKey = isVertical ? 'ArrowUp' : 'ArrowLeft';
		const isNext = event.key === nextKey;
		const isPrev = event.key === prevKey;
		const isHome = event.key === 'Home';
		const isEnd = event.key === 'End';

		if (!isNext && !isPrev && !isHome && !isEnd) {
			return;
		}

		const triggers = Array.from(event.currentTarget.querySelectorAll<HTMLButtonElement>('button[role="tab"]')).filter((trigger) => !trigger.disabled);

		if (triggers.length === 0) {
			return;
		}

		const currentIndex = triggers.indexOf(document.activeElement as HTMLButtonElement);
		let nextIndex: number;
		if (isHome) {
			nextIndex = 0;
		} else if (isEnd) {
			nextIndex = triggers.length - 1;
		} else {
			const direction = isNext ? 1 : -1;
			nextIndex = (currentIndex + direction + triggers.length) % triggers.length;
		}

		const nextTrigger = triggers[nextIndex];
		nextTrigger?.focus();

		// 自动激活：方向键移动焦点时同步选中对应标签页。
		const nextValue = nextTrigger?.getAttribute('data-value');
		if (nextValue !== null && nextValue !== undefined) {
			context.select(nextValue);
		}

		event.preventDefault();
	}

	return (
		<div
			ref={(element) => {
				listRef.current = element;
				if (typeof ref === 'function') return ref(element);
				if (ref) ref.current = element;
			}}
			role="tablist"
			data-orientation={context.orientation}
			data-variant={variant}
			onKeyDown={handleKeyDown}
			className={`${styles[tabsStyleKeys.list]} ${styles[variantKey]} ${className}`}
			{...props}>
			{children}
			<span ref={indicatorRef} aria-hidden="true" data-slot="tabs-indicator" data-state="hidden" className={styles.indicator} />
		</div>
	);
});
TabsList.displayName = 'TabsList';

export interface TabsTriggerProps extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, 'value'>, TabsTriggerBaseProps {
	value: string;
}

const TabsTrigger = React.forwardRef<HTMLButtonElement, TabsTriggerProps>(({ className = '', value, disabled = false, children, onClick, ...props }, ref) => {
	const context = useTabsContext();
	const active = context.value === value;
	const state = getTabsState(active);
	const triggerId = `${context.baseId}-trigger-${value}`;
	const contentId = `${context.baseId}-content-${value}`;

	function handleClick(event: React.MouseEvent<HTMLButtonElement>) {
		context.select(value);
		onClick?.(event);
	}

	return (
		<button
			ref={ref}
			type="button"
			id={triggerId}
			role="tab"
			aria-selected={active}
			aria-controls={contentId}
			data-value={value}
			tabIndex={active ? 0 : -1}
			disabled={disabled}
			data-state={state}
			data-orientation={context.orientation}
			className={`${styles[tabsStyleKeys.trigger]} ${className}`}
			onClick={handleClick}
			{...props}>
			{children}
		</button>
	);
});
TabsTrigger.displayName = 'TabsTrigger';

export interface TabsContentProps extends React.HTMLAttributes<HTMLDivElement>, TabsContentBaseProps {
	value: string;
}

const TabsContent = React.forwardRef<HTMLDivElement, TabsContentProps>(({ className = '', value, children, ...props }, ref) => {
	const context = useTabsContext();
	const active = context.value === value;
	const state = getTabsState(active);
	const triggerId = `${context.baseId}-trigger-${value}`;
	const contentId = `${context.baseId}-content-${value}`;

	return (
		<div
			{...props}
			ref={ref}
			id={contentId}
			role="tabpanel"
			aria-labelledby={triggerId}
			data-state={state}
			data-orientation={context.orientation}
			hidden={!active}
			className={`${styles[tabsStyleKeys.content]} ${className}`}>
			{children}
		</div>
	);
});
TabsContent.displayName = 'TabsContent';

export { Tabs, TabsList, TabsTrigger, TabsContent };
export default Tabs;

@use '../../../styles/variables/colors' as *;

.root {
	display: flex;
	gap: var(--tile-tabs-gap, $spacing-2);
	font-weight: var(--tile-tabs-root-font-weight, inherit);

	&[data-orientation='horizontal'] {
		flex-direction: column;
	}

	&[data-orientation='vertical'] {
		flex-direction: row;
	}
}

.list {
	position: var(--tile-tabs-list-position, static);
	isolation: var(--tile-tabs-list-isolation, auto);
	display: inline-flex;
	width: fit-content;
	align-items: var(--tile-tabs-list-align, center);
	justify-content: center;
	border-radius: var(--tile-tabs-list-radius, $radius-lg);
	padding: var(--tile-tabs-list-padding, 3px);
	background-color: var(--tile-tabs-list-background, $muted);
	color: var(--tile-tabs-list-foreground, var(--tile-tabs-foreground, $muted-foreground));
	box-shadow: var(--tile-tabs-list-shadow, none);
	transition: background-color $transition-fast;
	outline: none;

	&::before {
		content: var(--tile-tabs-track-ring-content, none);
		position: absolute;
		inset: 0;
		border-radius: inherit;
		box-shadow: var(--tile-tabs-track-ring-shadow, none);
		pointer-events: none;
	}

	&:focus-visible {
		box-shadow: var(--tile-tabs-focus-shadow, 0 0 0 2px $background, 0 0 0 4px $ring);
	}

	&[data-orientation='horizontal'] {
		height: var(--tile-tabs-list-height, 2.25rem);
	}

	&[data-orientation='vertical'] {
		height: fit-content;
		flex-direction: column;
	}

	// 变体
	&.variantLine {
		gap: var(--tile-tabs-line-gap, $spacing-1);
		background-color: transparent;
		border-radius: 0;
		padding: var(--tile-tabs-line-padding, 3px);
		box-shadow: var(--tile-tabs-line-shadow, none);
		border-bottom: var(--tile-tabs-line-border-bottom, 0 solid transparent);
		border-color: var(--tile-tabs-line-border-color, currentcolor);

		&::before {
			content: none;
		}

		&[data-orientation='horizontal'] {
			height: var(--tile-tabs-line-height, 2.25rem);
		}

		> .trigger[data-state='active'] {
			background-color: transparent;
			box-shadow: none;

			&::after {
				display: var(--tile-tabs-active-pseudo-display, block);
				content: '';
				position: absolute;
				background-color: var(--tile-tabs-line-color, $foreground);
			}
		}

		&[data-orientation='horizontal'] > .trigger[data-state='active']::after {
			left: 0;
			right: 0;
			bottom: -5px;
			height: 2px;
		}

		&[data-orientation='vertical'] > .trigger[data-state='active']::after {
			top: 0;
			bottom: 0;
			right: -4px;
			width: 2px;
		}
	}
}

.trigger {
	position: relative;
	z-index: var(--tile-tabs-trigger-z-index, auto);
	display: inline-flex;
	flex: var(--tile-tabs-trigger-flex, 1);
	align-items: center;
	justify-content: center;
	gap: $spacing-1_5;
	border: var(--tile-tabs-trigger-border-width, 1px) solid transparent;
	border-radius: var(--tile-tabs-trigger-radius, $radius-md);
	padding: var(--tile-tabs-trigger-padding, $spacing-1 $spacing-2);
	margin: var(--tile-tabs-trigger-margin, 0);
	font-size: var(--tile-tabs-font-size, $text-sm);
	font-weight: var(--tile-tabs-font-weight, $font-medium);
	white-space: nowrap;
	color: var(--tile-tabs-foreground, $muted-foreground);
	transition:
		color $transition-fast,
		box-shadow $transition-fast;
	outline: none;
	user-select: none;

	&:hover {
		color: var(--tile-tabs-active-foreground, $foreground);
	}

	&:focus-visible {
		border-color: var(--tile-tabs-focus-border, $ring);
		box-shadow: var(--tile-tabs-trigger-focus-shadow, 0 0 0 3px color-mix(in srgb, $ring 50%, transparent));
	}

	&:disabled {
		pointer-events: none;
		opacity: 0.5;
	}

	&[data-state='active'] {
		background-color: var(--tile-tabs-active-background, $background);
		color: var(--tile-tabs-active-foreground, $foreground);
		box-shadow: var(--tile-tabs-active-shadow, $shadow-sm);
	}

	&[data-orientation='vertical'] {
		width: 100%;
		justify-content: flex-start;
	}

	svg {
		pointer-events: none;
		width: 1rem;
		height: 1rem;
		flex-shrink: 0;
	}
}

.content {
	flex: 1;
	border-radius: var(--tile-tabs-content-radius, $radius);
	outline: none;

	&:focus-visible {
		box-shadow: var(--tile-tabs-trigger-focus-shadow, 0 0 0 3px color-mix(in srgb, $ring 50%, transparent));
	}
}

// One independent indicator per list. It is inert in the original Tile theme.
.indicator {
	display: var(--tile-tabs-indicator-display, none);
	position: absolute;
	pointer-events: none;
	z-index: 0;
	left: 0;
	top: 0;
	width: var(--tile-tabs-indicator-width, 0px);
	height: var(--tile-tabs-indicator-height, 0px);
	transform: translate(var(--tile-tabs-indicator-left, 0px), var(--tile-tabs-indicator-top, 0px));
	border-radius: var(--tile-tabs-indicator-radius, $radius-md);
	background-color: var(--tile-tabs-indicator-background, $background);
	box-shadow: var(--tile-tabs-indicator-shadow, $shadow-sm);
	transition:
		transform 200ms ease,
		width 200ms ease,
		height 200ms ease;

	&[data-state='hidden'] {
		visibility: hidden;
	}
}

.variantLine {
	> .trigger {
		padding: var(--tile-tabs-line-trigger-padding, $spacing-1 $spacing-2);
		margin: var(--tile-tabs-line-trigger-margin, 0);
		border-radius: var(--tile-tabs-line-trigger-radius, $radius-md);

		&:hover {
			background-color: var(--tile-tabs-line-hover-background, transparent);
		}
	}

	&[data-orientation='horizontal'] > .indicator {
		top: auto;
		bottom: 0;
		height: 2px;
		transform: translateX(var(--tile-tabs-indicator-left, 0px));
		border-radius: 0;
		background-color: var(--tile-tabs-line-color, $foreground);
		box-shadow: none;
	}

	&[data-orientation='vertical'] > .indicator {
		left: auto;
		inset-inline-end: 0;
		width: 2px;
		transform: translateY(var(--tile-tabs-indicator-top, 0px));
		border-radius: 0;
		background-color: var(--tile-tabs-line-color, $foreground);
		box-shadow: none;
	}
}

// Selected-state shadows otherwise override keyboard focus, especially in line lists.
.trigger[data-state='active']:focus-visible {
	box-shadow: var(--tile-tabs-trigger-focus-shadow, var(--tile-tabs-active-shadow, $shadow-sm));
}

.list.variantLine > .trigger[data-state='active']:focus-visible {
	box-shadow: var(--tile-tabs-trigger-focus-shadow, none);
}

@media (prefers-reduced-motion: reduce) {
	.indicator {
		transition: none;
	}
}
